use std::collections::BTreeMap;

use callisto_model::{
    CommandRunner, Diagnostic, DiagnosticCode, DiagnosticSeverity, Package, PackageId, Severity, StatusReport,
    SCHEMA_VERSION,
};

use crate::aggregate::LoadedChangeset;
use crate::changed::changed_since_last_tag;
use crate::commands::escalate;
use crate::commands::version::{plan_version, VersionOptions};
use crate::error::GraphError;
use crate::infer::SeverityInference;
use crate::resolver::DependencyResolver;
use crate::Workspace;

#[derive(Clone, Debug, Default)]
pub struct StatusOptions {
    pub strict: bool,
}

/// Per-package accumulator: pending changeset names and their max severity.
type PendingChangesets = BTreeMap<PackageId, (Vec<String>, Option<Severity>)>;

/// Resolves each changeset entry to at most one package and accumulates the
/// pending changeset names and max severity per package.
///
/// Uses [`PackageId::resolve_unique`] -- the same primitive
/// `changeset_wellformedness_diagnostics` uses below, kept as the one
/// resolution path -- rather than a bare `matches()` loop, so a changeset
/// entry naming a bare package that exists in two or more ecosystems (e.g.
/// `cargo/foo` and `npm/foo`) is never silently attached to every matching
/// package. An unknown or ambiguous entry is skipped here rather than
/// hard-erroring: `changeset_wellformedness_diagnostics` reports both cases
/// as an Error-severity diagnostic instead.
fn resolve_pending_changesets<'a>(
    packages: impl Iterator<Item = &'a Package> + Clone,
    loaded_changesets: &[LoadedChangeset],
) -> PendingChangesets {
    let mut pending: PendingChangesets = BTreeMap::new();
    for lc in loaded_changesets {
        for entry in &lc.changeset.entries {
            let Ok(entry_id) = PackageId::parse(&entry.name) else {
                continue;
            };
            let Ok(Some(resolved)) = entry_id.resolve_unique(packages.clone(), |p| &p.id) else {
                continue;
            };
            let name = lc
                .path
                .file_stem()
                .and_then(|s| s.to_str())
                .unwrap_or("unknown")
                .to_string();
            let state = pending.entry(resolved.id.clone()).or_default();
            state.0.push(name);
            state.1 = match (state.1, entry.severity) {
                (None, s) => Some(s),
                (Some(cur), s) => Some(cur.max(s)),
            };
        }
    }
    pending
}

pub fn status<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
    ws: &Workspace<'_, R, D>,
    inference: &I,
    opts: &StatusOptions,
) -> Result<StatusReport, GraphError> {
    let mut packages = Vec::new();
    let base_versions = ws.base_versions()?;
    let (loaded_changesets, changeset_load_failures) = crate::load_changesets_permissive(&ws.root, &ws.config)?;
    let tags = ws.tags()?;

    let all_packages: Vec<&Package> = ws.graph.packages().collect();
    let pending = resolve_pending_changesets(all_packages.iter().copied(), &loaded_changesets);

    // Pending severity is `plan_version`'s own
    // `PlannedBump.severity` per package -- the same cascade/fixed/linked-group
    // computation `callisto version` uses. status computes no cascade of its
    // own; it only reads the plan `plan_version` already derives.
    let version_opts = VersionOptions {
        strict: opts.strict,
        allow_empty_changesets: true,
    };
    // An ambiguous changeset entry, or an unparseable changeset file, makes `plan_version`
    // (via `aggregate`'s own strict `load_changesets`) hard-error -- the right behavior for a
    // real `version`/`release` run, but `status` must survive both and report
    // `AmbiguousPackageName`/the parse failure diagnostic below instead. Severity planning is
    // skipped for this run rather than duplicating `aggregate`'s own resolution to route
    // around its error.
    let plan = match plan_version(ws, inference, &version_opts) {
        Ok(plan) => Some(plan),
        Err(GraphError::AmbiguousName { .. } | GraphError::ParseChangeset { .. }) => None,
        Err(e) => return Err(e),
    };
    let planned_severity: BTreeMap<PackageId, Severity> = plan
        .iter()
        .flat_map(|plan| &plan.bumps)
        .map(|b| (b.package.clone(), b.severity))
        .collect();

    let changed = changed_since_last_tag(&all_packages, tags, ws.git_access())?;

    for pkg in all_packages.iter().copied() {
        let current_version = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
            GraphError::Manifest(callisto_model::ManifestError::MissingField {
                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                field: "version",
            })
        })?;
        let last = tags.last_tag(&pkg.id);
        let last_tag = last.map(|t| t.name.clone());
        let last_released_version = last.map(|t| t.version.clone());

        let (pkg_changesets, _) = pending.get(&pkg.id).cloned().unwrap_or_default();
        let pending_severity = planned_severity.get(&pkg.id).copied();

        packages.push(callisto_model::StatusPackageRecord {
            package: pkg.id.clone(),
            current_version,
            last_tag,
            last_released_version,
            pending_severity,
            changed_since_last_tag: changed[&pkg.id],
            release_trigger: pkg.release_trigger,
            pending_changesets: pkg_changesets,
        });
    }

    let mut diagnostics = ws.graph.diagnostics().to_vec();
    // Fold in every well-formedness diagnostic `validate` used to
    // report (EmptyChangeset, UnknownPackage, AmbiguousPackageName,
    // InvalidPackageName) now that `validate` is gone.
    diagnostics.extend(changeset_wellformedness_diagnostics(
        all_packages.iter().copied(),
        &loaded_changesets,
    ));
    for failure in &changeset_load_failures {
        diagnostics.push(Diagnostic {
            code: DiagnosticCode::ChangesetParseFailed,
            severity: DiagnosticSeverity::Error,
            message: format!("{}: {}", failure.path.display(), failure.source),
            package: None,
            path: Some(failure.path.clone()),
            governed_by: None,
            escalated_by: None,
        });
    }
    escalate(&mut diagnostics, opts.strict);

    let has_changesets = packages.iter().any(|p| !p.pending_changesets.is_empty());
    // Count of packages with a planned bump, post-cascade/fixed/linked-group --
    // the field a script now reads to detect pending changesets, since `--check`'s
    // exit code no longer signals it.
    let pending = packages.iter().filter(|p| p.pending_severity.is_some()).count() as u32;

    Ok(StatusReport {
        schema_version: SCHEMA_VERSION,
        has_changesets,
        pending,
        packages,
        diagnostics,
    })
}

/// The per-changeset well-formedness diagnostics `validate` used to emit
/// (crates/callisto-graph/src/commands/validate.rs, now removed): entries shape and
/// package-name resolution. Uses the same `resolve_unique` primitive
/// `resolve_pending_changesets` does, but this scan must never abort early,
/// so an unknown or ambiguous entry becomes a diagnostic instead of an
/// early return.
///
/// An entries-empty changeset is advisory only (`Info`): `@changesets/cli add --empty`
/// produces one deliberately, so it is not a well-formedness problem. A changeset with
/// entries but an empty summary never reaches this scan at all -- `load_changesets_permissive`
/// already rejects that shape at parse time, surfacing it as a `ChangesetParseFailed`
/// diagnostic instead.
fn changeset_wellformedness_diagnostics<'a>(
    packages: impl Iterator<Item = &'a Package> + Clone,
    loaded: &[LoadedChangeset],
) -> Vec<Diagnostic> {
    let mut diagnostics = Vec::new();
    for cs in loaded {
        if cs.changeset.entries.is_empty() {
            diagnostics.push(Diagnostic {
                code: DiagnosticCode::EmptyChangeset,
                severity: DiagnosticSeverity::Info,
                message: format!("Changeset `{}` is empty", cs.path.display()),
                package: None,
                path: Some(cs.path.clone()),
                governed_by: None,
                escalated_by: None,
            });
        }

        for entry in &cs.changeset.entries {
            match PackageId::parse(&entry.name) {
                Ok(id) => match id.resolve_unique(packages.clone(), |p| &p.id) {
                    Ok(None) => {
                        diagnostics.push(Diagnostic {
                            code: DiagnosticCode::UnknownPackage,
                            severity: DiagnosticSeverity::Error,
                            message: format!(
                                "Changeset `{}` references unknown package `{}`",
                                cs.path.display(),
                                entry.name
                            ),
                            package: Some(id),
                            path: Some(cs.path.clone()),
                            governed_by: None,
                            escalated_by: None,
                        });
                    }
                    Ok(Some(_)) => {}
                    Err(candidates) => {
                        let names: Vec<String> = candidates.iter().map(|p| p.id.display_name().to_string()).collect();
                        diagnostics.push(Diagnostic {
                            code: DiagnosticCode::AmbiguousPackageName,
                            severity: DiagnosticSeverity::Error,
                            message: format!(
                                "Changeset `{}` references ambiguous package `{}` (matches: {})",
                                cs.path.display(),
                                entry.name,
                                names.join(", ")
                            ),
                            package: Some(id),
                            path: Some(cs.path.clone()),
                            governed_by: None,
                            escalated_by: None,
                        });
                    }
                },
                Err(_) => {
                    diagnostics.push(Diagnostic {
                        code: DiagnosticCode::InvalidPackageName,
                        severity: DiagnosticSeverity::Error,
                        message: format!(
                            "Changeset `{}` contains invalid package name `{}`",
                            cs.path.display(),
                            entry.name
                        ),
                        package: None,
                        path: Some(cs.path.clone()),
                        governed_by: None,
                        escalated_by: None,
                    });
                }
            }
        }
    }
    diagnostics
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    use callisto_model::format::{Changeset, Entry};
    ///
    /// `Bare(x)` matches any `Prefixed(_, x)` (bare is an ecosystem wildcard);
    /// `Prefixed(e1, x)` matches `Prefixed(e2, x)` only if `e1 == e2`; exact
    /// equality always matches.
    ///
    /// **Caller contract**: in a polyglot workspace, a bare lookup can match
    /// packages in two or more ecosystems (e.g. `foo` in both Cargo and npm).
    /// Callers must collect *all* matches and error on 2+ — see
    /// `aggregate::resolve_target_package`'s `AmbiguousName` pattern — never
    /// take the first match silently. A plain existence check (`.any()`) is
    /// safe only because the aggregation layer already rejects ambiguous
    /// references upstream.
    pub fn matches(&self, other: &Self) -> bool {
        if self == other {
            return true;
        }
        if self.name() == other.name() {
            match (self.ecosystem(), other.ecosystem()) {
                (None, _) | (_, None) => true,
                (Some(e1), Some(e2)) => e1 == e2,
            }
        } else {
            false
        }
    }

    /// The single implementation of the collect-and-error pattern
    /// [`matches`](Self::matches)'s own doc comment requires every caller
    /// to hand-roll: filters `items` down to those whose id (via `id_of`)
    /// matches `self`, then resolves the result to exactly one, none, or
    /// reports the ambiguity.
    ///
    /// - `Ok(None)`: no item matches.
    /// - `Ok(Some(item))`: exactly one item matches -- the unambiguous case.
    /// - `Err(candidates)`: two or more items match. The caller decides how
    ///   to report this (e.g. as a domain-specific "ambiguous name" error
    ///   naming `self` and `candidates`) -- this method stays generic over
    ///   any `T` (a `Package`, a bare `PackageId`, ...) rather than forcing
    ///   a particular error type on every layer that needs this check.
    pub fn resolve_unique<'a, T>(
        &self,
        items: impl Iterator<Item = &'a T>,
        id_of: impl Fn(&'a T) -> &'a PackageId,
    ) -> Result<Option<&'a T>, Vec<&'a T>> {
        let matching: Vec<&'a T> = items.filter(|item| id_of(item).matches(self)).collect();
        match matching.len() {
            0 => Ok(None),
            1 => Ok(Some(matching[0])),
            _ => Err(matching),
        }
    }
}

impl fmt::Display for PackageId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.display_name())
    }
}

impl FromStr for PackageId {
    type Err = PackageIdParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        PackageId::parse(s)
    }
}

impl PartialOrd for PackageId {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for PackageId {
    fn cmp(&self, other: &Self) -> Ordering {
        let key_self = (self.ecosystem(), self.name());
        let key_other = (other.ecosystem(), other.name());
        key_self.cmp(&key_other)
    }
}

impl Serialize for PackageId {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(&self.display_name())
    }
}

impl TryFrom<String> for PackageId {
    type Error = PackageIdParseError;

    fn try_from(raw: String) -> Result<Self, Self::Error> {
        Self::parse(&raw)
    }
}

/// Errors produced by [`PackageId::parse`].
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum PackageIdParseError {
    #[error("package identity is empty")]
    Empty,
    #[error("package identity `{raw}` has ecosystem prefix `{prefix}` but no name after it")]
    EmptyNameAfterPrefix { raw: String, prefix: String },
    #[error("`{raw}` starts with `/`")]
    LeadingSlash { raw: String },
    #[error("package identity `{raw}` contains path traversal `..`")]
    PathTraversal { raw: String },
    #[error("package identity `{raw}` starts with `-`, which could be misread as a command-line flag")]

//! `status` and `version` must attach a changeset entry to the same package for every selector kind.
use std::collections::BTreeSet;
use std::fs;
use std::path::Path;
use std::process::Command;

fn run(root: &Path, args: &[&str]) -> (Option<i32>, String, String) {
    let out = Command::new(env!("CARGO_BIN_EXE_callisto"))
        .args(["--format", "json", "--cwd", root.to_str().unwrap()])
        .args(args)
        .env("__CALLISTO_TEST_SLEEP_SCALE", "0")
        .output()
        .unwrap();
    (
        out.status.code(),
        String::from_utf8_lossy(&out.stdout).into_owned(),
        String::from_utf8_lossy(&out.stderr).into_owned(),
    )
}

fn cargo_pkg(root: &Path, dir: &str, name: &str, version: &str) {
    fs::create_dir_all(root.join(dir).join("src")).unwrap();
    fs::write(
        root.join(dir).join("Cargo.toml"),
        format!("[package]\nname = \"{name}\"\nversion = \"{version}\"\nedition = \"2021\"\n"),
    )
    .unwrap();
    fs::write(root.join(dir).join("src/lib.rs"), "\n").unwrap();
}

fn npm_pkg(root: &Path, dir: &str, name: &str, version: &str) {
    fs::create_dir_all(root.join(dir)).unwrap();
    fs::write(
        root.join(dir).join("package.json"),
        format!("{{\n  \"name\": \"{name}\",\n  \"version\": \"{version}\"\n}}\n"),
    )
    .unwrap();
}

fn workspace(members: &[&str]) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    callisto_fixtures::git::init_repo(root);
    let list: Vec<String> = members.iter().map(|m| format!("\"{m}\"")).collect();
    fs::write(
        root.join("Cargo.toml"),
        format!("[workspace]\nmembers = [{}]\nresolver = \"2\"\n", list.join(", ")),
    )
    .unwrap();
    callisto_fixtures::scaffold_callisto(root);
    dir
}

fn commit(root: &Path) {
    for args in [vec!["add", "-A"], vec!["commit", "-m", "fixture"]] {
        let out = Command::new("git").args(&args).current_dir(root).output().unwrap();
        assert!(
            out.status.success(),
            "git {args:?}: {}",
            String::from_utf8_lossy(&out.stderr)
        );
    }
}

/// Cargo `foo` alone.
fn unique() -> tempfile::TempDir {
    let dir = workspace(&["crates/foo"]);
    cargo_pkg(dir.path(), "crates/foo", "foo", "1.0.0");
    commit(dir.path());
    dir
}

/// One directory holding Cargo `native-core` and npm `@org/native-core-js`.
fn dual() -> tempfile::TempDir {
    let dir = workspace(&["crates/native-core"]);
    cargo_pkg(dir.path(), "crates/native-core", "native-core", "1.0.0");
    npm_pkg(dir.path(), "crates/native-core", "@org/native-core-js", "1.0.0");
    commit(dir.path());
    dir
}

/// Cargo `foo` and npm `foo` in different directories, so both are promoted.
fn promoted() -> tempfile::TempDir {
    let dir = workspace(&["crates/foo"]);
    cargo_pkg(dir.path(), "crates/foo", "foo", "1.0.0");
    npm_pkg(dir.path(), "packages/foo", "foo", "3.0.0");
    commit(dir.path());
    dir
}

/// Package `x` (Cargo `x`, npm `shared`) next to a separate Cargo `shared`.
fn secondary_name_collides_with_a_primary_name() -> tempfile::TempDir {
    let dir = workspace(&["crates/x", "crates/shared"]);
    cargo_pkg(dir.path(), "crates/x", "x", "1.0.0");
    npm_pkg(dir.path(), "crates/x", "shared", "1.0.0");
    cargo_pkg(dir.path(), "crates/shared", "shared", "2.0.0");
    commit(dir.path());
    dir
}

#[derive(Debug)]
struct Outcome {
    exit: Option<i32>,
    /// Packages the changeset entry is attached to; empty when the command rejected or ignored it.
    packages: BTreeSet<String>,
    /// Error-level diagnostic codes, or the failing command's error code.
    errors: Vec<String>,
}

fn package_names(value: &serde_json::Value, field: &str) -> Vec<String> {
    value[field]
        .as_array()
        .into_iter()
        .flatten()
        .map(|item| item["package"].as_str().unwrap_or_default().to_string())
        .collect()
}

fn status_outcome(root: &Path) -> Outcome {
    let (exit, stdout, _) = run(root, &["status", "--check"]);
    let report: serde_json::Value = serde_json::from_str(&stdout).expect("status prints a JSON report");
    let errors: Vec<String> = report["diagnostics"]
        .as_array()
        .into_iter()
        .flatten()
        .filter(|d| d["severity"] == "error")
        .map(|d| d["code"].as_str().unwrap_or_default().to_string())
        .collect();
    let attached = report["packages"]
        .as_array()
        .into_iter()
        .flatten()
        .filter(|p| p["pendingChangesets"].as_array().is_some_and(|a| !a.is_empty()))
        .map(|p| p["package"].as_str().unwrap_or_default().to_string());
    let packages = if errors.is_empty() {
        attached.collect()
    } else {
        BTreeSet::new()
    };
    Outcome { exit, packages, errors }
}

fn version_outcome(root: &Path) -> Outcome {
    let (exit, stdout, stderr) = run(root, &["version", "--dry-run"]);
    if exit == Some(0) {
        let report: serde_json::Value = serde_json::from_str(&stdout).expect("version prints a JSON report");
        let packages = package_names(&report, "bumps").into_iter().collect();
        return Outcome {
            exit,
            packages,
            errors: Vec::new(),
        };
    }
    let report: serde_json::Value = serde_json::from_str(&stderr).expect("version prints a JSON error");
    Outcome {
        exit,
        packages: BTreeSet::new(),
        errors: vec![report["error"]["code"].as_str().unwrap_or_default().to_string()],
    }
}

/// Writes a changeset naming `selector` and runs both commands against it.
fn outcomes(root: &Path, selector: &str) -> (Outcome, Outcome) {
    fs::write(
        root.join(".changeset/probe.md"),
        format!("---\n\"{selector}\": minor\n---\n\nChange.\n"),
    )
    .unwrap();
    (status_outcome(root), version_outcome(root))
}

fn assert_same_packages(root: &Path, selector: &str) {
    let (status, version) = outcomes(root, selector);
    assert_eq!(
        status.packages, version.packages,
        "selector `{selector}` resolves differently:\n  status:  {status:?}\n  version: {version:?}"
    );
}

#[test]
fn unique_package_bare_and_qualified_selectors_agree() {
    let dir = unique();
    for selector in ["foo", "cargo/foo", "cargo:foo"] {
        assert_same_packages(dir.path(), selector);
        let (status, version) = outcomes(dir.path(), selector);
        assert_eq!(status.packages, BTreeSet::from(["foo".to_string()]), "{selector}");
        assert_eq!(version.packages, BTreeSet::from(["foo".to_string()]), "{selector}");
    }
}

